glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
#if USE_LOCAL
  layout(std140) uniform CCLocal {
    highp mat4 cc_matWorld;
    highp mat4 cc_matWorldIT;
    highp vec4 cc_lightingMapUVParam;
    highp vec4 cc_localShadowBias;
    highp vec4 cc_reflectionProbeData1;
    highp vec4 cc_reflectionProbeData2;
    highp vec4 cc_reflectionProbeBlendData1;
    highp vec4 cc_reflectionProbeBlendData2;
  };
#endif
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec2 uv;
out vec4 tint;
vec4 vert () {
  vec4 p=vec4(a_position,1.0);
  #if USE_LOCAL
    p=cc_matWorld*p;
  #endif
  uv=a_texCoord;
  tint=a_color;
  return cc_matViewProj*p;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
uniform sampler2D cc_spriteTexture;
uniform sampler2D foilGrain;
layout(std140) uniform CoatLight { vec4 tiltFinish; };
in vec2 uv;
in vec4 tint;
float bell(float x,float w) { float k=x/w; return exp(-k*k); }
vec3 spectrum(float phase) {
    return .57+.43*cos(6.28318*(vec3(.00,.74,.54)+phase));
}
float engravedLine(float phase,float width) {
    float d=abs(fract(phase)-.5);
    return 1.-smoothstep(width*.28,width,d);
}
vec4 frag () {
    vec2 p=uv;
    vec2 turn=tiltFinish.xy;
    float finish=tiltFinish.z;
    vec2 shape=abs((p-.5)*vec2(192.,272.))-vec2(86.3,126.3);
    float distance=length(max(shape,vec2(0.)))+min(max(shape.x,shape.y),0.)-9.3;
    float silhouette=1.-smoothstep(-.65,.05,distance);
    if(silhouette<.001)return vec4(0.);
    vec3 die=texture(cc_spriteTexture,p).rgb;
    vec2 q=(p-vec2(.47,.44))*vec2(1.,1.4167);
    vec2 r=q+vec2(1.15*turn.x+.11*turn.y,1.13*turn.y-.12*turn.x);
    float across=dot(r,vec2(.885,-.465))+.20;
    float along=dot(r,vec2(.465,.885))+.09;
    float key=bell(across,.245)*bell(along,.86);
    float strip=bell(across-.13,.050)*bell(along,.68);
    float opposite=bell(dot(r,vec2(.94,.342))-.37,.096)*bell(r.y-.12,.72);
    float flankLight=bell(abs(dot(r,vec2(.96,.28)))-.93,.155)*bell(r.y,1.38);
    float grazing=flankLight*smoothstep(.26,.84,length(turn));
    float land=die.b;
    float border=1.-smoothstep(.015,.093,min(min(p.x,1.-p.x),min(p.y,1.-p.y)*1.4167));
    float fresnel=smoothstep(.18,1.20,length(turn));
    float lip=bell(distance+1.16,.72)*(.28+.72*key);
    vec3 tintLight=vec3(.88,.92,.95);
    float coverage;
    if(finish<.5){
        vec3 scale=texture(foilGrain,p*vec2(.94,1.86)+vec2(.21,.13)).rgb;
        vec2 n=scale.rg*2.-1.;
        float course=24.*p.y+1.85*sin(9.*p.x+2.3*p.y)+.72*sin(21.*p.x-4.8*p.y);
        float chasing=engravedLine(course,.15)+.48*engravedLine(course+.23,.085);
        float facet=bell(length(n-(turn*.85+vec2(.14,-.16))),.42)*scale.b;
        float ribbon=bell(across+.17*n.x,.32);
        float lipLight=bell(across+.14*n.x-.11,.058);
        float trim=(.27+.73*land)*(.25+.75*scale.b);
        coverage=(.63*facet*(.48+.80*ribbon+.36*grazing)
                 +chasing*(.17+.80*ribbon+.32*grazing)
                 +.43*lipLight*(.35+.65*facet))*trim+.083*lip+.022*key;
        float gild=clamp(.17+.46*facet+.31*chasing+.26*lipLight,0.,1.);
        tintLight=mix(vec3(.76,.28,.11),vec3(1.,.92,.66),gild);
    }else if(finish<1.5){
        vec3 water=texture(foilGrain,vec2(.57*p.x+.15*p.y,2.75*p.y)+vec2(.16,.22)).rgb;
        vec2 n=water.rg*2.-1.;
        float bend=.072*sin(11.*p.x+3.4*p.y)+.023*sin(25.*p.x-3.5*p.y);
        float flow=8.2*(p.y+.31*p.x+bend);
        float waves=engravedLine(flow,.12)+.50*engravedLine(flow+.18+.09*sin(14.*p.x),.085);
        float eddy=bell(across+.13*sin(p.y*10.)+.10*n.x,.33);
        float crest=bell(length(n-vec2(.88*turn.x+.08,.73*turn.y-.17)),.38)*water.b;
        float rill=bell(across+.18*n.x+.09,.077);
        float bed=.24+.76*land;
        coverage=((.14+.77*eddy+.36*grazing)*waves*(.49+.51*water.b)
                 +.68*crest*(.50+.73*eddy)+.28*rill*(.34+.66*water.b))*bed+.087*lip+.023*key;
        float foam=clamp(.08+.50*waves+.39*crest+.24*rill,0.,1.);
        tintLight=mix(vec3(.13,.69,.59),vec3(.83,1.,.94),foam);
    }else if(finish<2.5){
        vec3 grain=texture(foilGrain,p*vec2(.73,1.46)+vec2(.073,.127)).rgb;
        vec2 n=grain.rg*2.-1.;
        float hit=bell(length(n-(turn*1.04+vec2(.13,-.19))),.31);
        float roll=bell(across+.045,.21)*bell(along,.86);
        float deposit=.08+.92*land;
        float flakes=hit*(.23+.84*roll)*deposit*(.50+.50*grain.b);
        float feathers=die.r*(.16+1.29*key+.57*opposite+.48*grazing)*(.55+.45*land);
        float rainbowBand=bell(across+.045,.145)*bell(along,.82);
        float optical=clamp((.049*key+.042*opposite)+(.26*rainbowBand+.12*grazing)*land+flakes+feathers,0.,.88);
        vec3 pearl=spectrum(.99*p.x+.53*p.y+.24*n.x-.67*turn.x+.34*turn.y);
        vec3 mica=mix(vec3(.58,.76,.97),pearl,.74+.13*rainbowBand);
        tintLight=mix(mica,vec3(.97,.98,1.),clamp(hit*.43+strip*.43+feathers*.30,0.,.87));
        coverage=optical+.105*strip*(.24+.76*land)+.10*lip;
    }else{
        vec3 shell=texture(foilGrain,p*vec2(2.12,4.02)+vec2(.31,.11)).rgb;
        vec2 n=shell.rg*2.-1.;
        float angle=dot(n,vec2(.74,.42))-dot(turn,vec2(.87,.59));
        float tile=bell(angle+.18*across,.185)*smoothstep(.42,.83,shell.b);
        float chisel=engravedLine(32.*p.y+15.*p.x+3.1*shell.r+.72*sin(9.*p.x),.115);
        float sweep=bell(across-.19*n.x,.34);
        float bevel=bell(across+.16*n.y+.08,.068);
        float facet=bell(length(n-turn*.86-vec2(.10,.21)),.255);
        float silver=(.09+.76*sweep+.36*grazing)*tile;
        float cut=chisel*(.14+.54*sweep+.31*opposite)*(.42+.58*tile);
        float deposit=.095+.905*land*land;
        float turnIn=.29+.71*smoothstep(.035,.38,length(turn));
        float plaque=smoothstep(.70,.75,p.y)*(1.-smoothstep(.958,.986,p.y))
                    *smoothstep(.035,.07,p.x)*(1.-smoothstep(.93,.965,p.x));
        coverage=((silver+cut+.59*facet+.19*bevel)*deposit*turnIn+.014*key)*(1.-.92*plaque)+.091*lip;
        vec3 pearl=spectrum(.46+.48*shell.r+.12*shell.g+.56*angle);
        vec3 nacre=mix(vec3(.83,.86,.90),pearl,.24+.15*tile);
        tintLight=mix(nacre,vec3(.99,.995,1.),clamp(.57*facet+.30*bevel+.28*chisel,0.,1.));
    }
    if(finish<1.5 || finish>2.5){
        float insideX=smoothstep(.11,.17,p.x)*(1.-smoothstep(.83,.89,p.x));
        float insideY=smoothstep(.72,.77,p.y)*(1.-smoothstep(.93,.965,p.y));
        coverage*=1.-.80*insideX*insideY;
    }
    if(tiltFinish.w>.5){
        float rules=smoothstep(.69,.75,p.y)*(1.-smoothstep(.95,.983,p.y));
        float leftHardware=(1.-smoothstep(.17,.23,p.x))*(1.-smoothstep(.34,.40,p.y));
        float jadeBand=(1.-smoothstep(.12,.16,p.y))*(1.-smoothstep(.35,.41,p.x));
        coverage*=1.-.95*max(rules*smoothstep(.08,.15,p.x)*(1.-smoothstep(.86,.94,p.x)),max(leftHardware,jadeBand));
    }
    return vec4(tintLight,clamp(coverage,0.,.81)*silhouette*tint.a);
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

